// Calcula o início do dia atual no fuso horário local
import "timezone"
option location = timezone.location(name: "America/Sao_Paulo") // AJUSTE SEU FUSO HORÁRIO
startOfDay = today()


// Define a tarifa (pode usar variável do Grafana ${tarifa_kwh})
tarifa = ${tarifa_kwh}

from(bucket: "$bucket")
  |> range(start: startOfDay) // Começa do início do dia atual
  |> filter(fn: (r) => r["_measurement"] == "consumo_energia")
  |> filter(fn: (r) => r["_field"] == "potencia_W")
  |> filter(fn: (r) => r["mac_medidor"] == "$mac_medidor")
  // Calcula a energia em Watt-minuto (Potência * 1 minuto) - assume 1 ponto por minuto
  // Se houver falhas, integral() é mais robusto, mas sum() é mais simples aqui.
  |> sum(column: "_value") // Soma todas as potências (W) do dia
  |> map(fn: (r) => ({
      _value: r._value / 60000.0 // Converte Watt-minuto para kWh (divide por 60 * 1000)
      })
  )
  |> keep(columns: ["_value"])
  |> yield(name: "Consumo Hoje (kWh)")

