tarifa = ${tarifa_kwh}

from(bucket: "$bucket")
  // Use o seletor de tempo do Grafana
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "consumo_energia")
  |> filter(fn: (r) => r["_field"] == "potencia_W")
  |> filter(fn: (r) => r["mac_medidor"] == "$mac_medidor")
  // Agrega por dia, alinhado com UTC (offset removido)
  |> aggregateWindow(every: 1d, fn: sum, timeSrc: "_start")
  // Converte W-min para kWh
  |> map(fn: (r) => ({
      _time: r._time, // Mantém o timestamp do início do dia
      _value: r._value / 60000.0
      })
  )
  |> yield(name: "Consumo Diário (kWh)")

